import React, { useState, useEffect } from 'react';
import styles from './Navbar.module.css';

const Navbar = () => {
  const [activeSection, setActiveSection] = useState('hero');
  const [isScrolled, setIsScrolled] = useState(false);

  const sections = [
    { id: 'hero', label: '~/home', icon: '🏠' },
    { id: 'education', label: 'education', icon: '🎓' },
    { id: 'skills', label: 'skills', icon: '⚡' },
    { id: 'projects', label: 'projects', icon: '📁' },
    { id: 'certifications', label: 'certs', icon: '📜' },
    { id: 'extracurricular', label: 'extra', icon: '🚀' },
    { id: 'contact', label: 'contact', icon: '📡' }
  ];

  useEffect(() => {
    const handleScroll = () => {
      // Change navbar background on scroll
      setIsScrolled(window.scrollY > 50);

      // Update active section based on scroll position
      const scrollPosition = window.scrollY + 100;

      for (const section of sections) {
        const element = document.getElementById(section.id);
        if (element) {
          const offsetTop = element.offsetTop;
          const offsetHeight = element.offsetHeight;

          if (scrollPosition >= offsetTop && scrollPosition < offsetTop + offsetHeight) {
            setActiveSection(section.id);
            break;
          }
        }
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [sections]);

  const handleClick = (e, sectionId) => {
    e.preventDefault();
    const element = document.getElementById(sectionId);
    if (element) {
      element.scrollIntoView({
        behavior: 'smooth',
        block: 'start'
      });
      setActiveSection(sectionId);
    }
  };

  return (
    <nav className={`${styles.navbar} ${isScrolled ? styles.scrolled : ''}`}>
      <div className={styles.container}>
        {/* Terminal Prompt */}
        <div className={styles.navPrompt}>
          <span className={styles.prompt}>safayet@portfolio</span>
          <span className={styles.colon}>:</span>
          <span className={styles.tilde}>~</span>
          <span className={styles.dollar}>$</span>
        </div>

        {/* Navigation Links */}
        <ul className={styles.navLinks}>
          {sections.map((section) => (
            <li key={section.id}>
              <a
                href={`#${section.id}`}
                onClick={(e) => handleClick(e, section.id)}
                className={`${styles.navLink} ${activeSection === section.id ? styles.active : ''}`}
              >
                <span className={styles.navIcon}>{section.icon}</span>
                <span className={styles.navLabel}>{section.label}</span>
                {activeSection === section.id && <span className={styles.cursor}>_</span>}
              </a>
            </li>
          ))}
        </ul>

        {/* Mobile Menu Toggle (Optional - for smaller screens) */}
        <div className={styles.mobileIndicator}>
          <span className={styles.prompt}>$</span>
          <span> cd {activeSection}</span>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
